using System;using System.IO;using System.Reflection;using ProgressPeek;
class SetupTests {
 public static int Run(){int failures=0;string root=Path.Combine(Path.GetTempPath(),"ProgressPeek-setup-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
  var migration=typeof(Storage).Assembly.GetType("ProgressPeek.StateMigration");if(migration==null){Console.WriteLine("FAIL: safe state migration boundary missing");failures++;}else{
   string old=Path.Combine(root,"old"),fresh=Path.Combine(root,"new");Directory.CreateDirectory(old);File.WriteAllText(Path.Combine(old,"settings.json"),"{\"ShowEta\":true,\"Enabled\":true}");File.WriteAllText(Path.Combine(old,"checks.json"),"{\"Day\":\"2026-10-01\",\"DailyCalls\":7}");File.WriteAllText(Path.Combine(old,"auth.json"),"private");Directory.CreateDirectory(Path.Combine(old,"updates"));File.WriteAllText(Path.Combine(old,"updates","unsafe.exe"),"unsafe");
   migration.GetMethod("CopyOnce").Invoke(null,new object[]{old,fresh});var store=new Storage(fresh);if(!store.Settings.ShowEta||store.Ledger.DailyCalls!=7||!File.Exists(Path.Combine(old,"settings.json"))||File.Exists(Path.Combine(fresh,"auth.json"))||Directory.Exists(Path.Combine(fresh,"updates"))){Console.WriteLine("FAIL: migration preferences, usage, exclusion or preservation");failures++;}
   File.WriteAllText(Path.Combine(fresh,"settings.json"),"{\"ShowEta\":false}");migration.GetMethod("CopyOnce").Invoke(null,new object[]{old,fresh});if(new Storage(fresh).Settings.ShowEta){Console.WriteLine("FAIL: existing destination overwritten");failures++;}
   string blocked=Path.Combine(root,"blocked");File.WriteAllText(blocked,"sentinel");object result=migration.GetMethod("CopyOnce").Invoke(null,new object[]{old,blocked});if(String.IsNullOrEmpty((string)result)||!File.Exists(Path.Combine(old,"checks.json"))){Console.WriteLine("FAIL: recoverable migration failure");failures++;}
  }
  var policy=typeof(Storage).Assembly.GetType("ProgressPeek.SetupConsent");if(policy==null){Console.WriteLine("FAIL: first-run consent boundary missing");failures++;}else{var store=new Storage(Path.Combine(root,"consent"));var allowed=policy.GetMethod("AllowsAi");if((bool)allowed.Invoke(null,new object[]{store.Settings})){Console.WriteLine("FAIL: fresh default enables AI before consent");failures++;}policy.GetMethod("Finish").Invoke(null,new object[]{store,false});if((bool)allowed.Invoke(null,new object[]{store.Settings})){Console.WriteLine("FAIL: declined AI is enabled");failures++;}policy.GetMethod("Finish").Invoke(null,new object[]{store,true});if(!(bool)allowed.Invoke(null,new object[]{new Storage(store.Folder).Settings})){Console.WriteLine("FAIL: explicit consent not persisted");failures++;}}
 }finally{Directory.Delete(root,true);}Console.WriteLine("Setup checks: failures="+failures);return failures;}
 [STAThread]static int Main(){return Run()==0?0:1;}
}
